<?php namespace Workspace; $pid=$project; ?>
<section class="panel"><h2>Книги проектов</h2><p>Публичные опубликованные страницы EngineBook 1.2.0. Подборки сохраняют исходный Markdown; это локальные снимки, не номера редакций Studio.</p><form method="get"><input type="hidden" name="p" value="book"><label>Проект<select name="project" required><?php selectOptions($projects,$pid) ?></select></label><button>Открыть</button></form></section>
<?php if($pid!==null): ?>
<section class="panel"><h2>Привязки книг</h2><ul><?php foreach($sources as $s): ?><li><a href="<?= h(url('book',['project'=>$pid,'source'=>$s['id']])) ?>"><?= h($s['name']) ?> · <?= h($s['scope']) ?></a> · <?= (int)$s['active']?'активна':'отключена' ?></li><?php endforeach ?></ul>
<?php if($available): ?><form method="post"><?php formFields('book.bind') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><label>Подключение<select name="connection"><?php selectOptions($available,null) ?></select></label><label>Книга/версия<input name="scope" required maxlength="129" placeholder="handbook/1.0"></label><label>Название<input name="name" required maxlength="120"></label><button class="primary">Привязать (MFA)</button></form><?php endif ?></section>
<?php if($source): $sid=(int)$source['id']; ?>
<section class="panel"><h2><?= h($source['name']) ?> · <?= h($source['scope']) ?></h2><?php if($user['role']==='owner'): ?><form method="post"><?php formFields('book.toggle') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="source_id" value="<?= $sid ?>"><input type="hidden" name="active" value="<?= (int)$source['active']?0:1 ?>"><button class="secondary"><?= (int)$source['active']?'Отключить':'Включить' ?> (MFA)</button></form><?php endif ?>
<?php if($error): ?><p class="planning-warning"><?= h($error) ?></p><?php endif ?><h3>Зафиксированные подборки</h3><ul><?php foreach($editions as $e): ?><li><a href="<?= h(url('book',['project'=>$pid,'edition'=>$e['id']])) ?>">#<?= (int)$e['id'] ?> <?= h($e['title']) ?></a> · <?= h(gmdate('Y-m-d H:i:s',(int)$e['created_at'])) ?> UTC</li><?php endforeach ?></ul><p>Последние 100 подборок; закреплённые за релизом доступны также из карточки выпуска.</p></section>
<?php if(!$edition&&!$error): ?><section class="panel"><h2>Каталог опубликованных страниц</h2><?php if(!$catalog): ?><p>Нет доступных страниц.</p><?php else: ?>
<?php if($write&&count($people)>=2): ?><form method="post"><?php formFields('book.capture') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="source_id" value="<?= $sid ?>"><label>Название подборки<input name="title" required maxlength="120"></label><label>Первый рецензент<select name="reviewer_a" required><option value="">Выберите</option><?php selectOptions(array_column($people,'name','id'),null) ?></select></label><label>Второй рецензент<select name="reviewer_b" required><option value="">Выберите другого</option><?php selectOptions(array_column($people,'name','id'),null) ?></select></label><p>Выберите 1–12 страниц. Содержимое будет сохранено и отправлено на независимую рецензию.</p><?php else: ?><p>Для создания подборки требуются полномочия work и два других участника с правами work и connections.</p><?php endif ?>
<?php foreach($catalog as $key=>$p): ?><div><?php if($write&&count($people)>=2): ?><label class="release-choice"><input type="checkbox" name="pages[]" value="<?= h($key) ?>"> <?= h($p['title']) ?> · <?= h($key) ?></label><?php else: ?><?= h($p['title']) ?> · <?= h($key) ?><?php endif ?> · <?= h($p['locale']) ?> · <?= h($p['updated']) ?> · <a href="<?= h(url('book',['project'=>$pid,'source'=>$sid,'page_key'=>$key])) ?>">Читать</a></div><?php endforeach ?>
<?php if($write&&count($people)>=2): ?><button class="primary">Зафиксировать и передать на рецензию (MFA)</button></form><?php endif ?><?php endif ?></section><?php endif ?>
<?php if($preview): ?><section class="panel"><h2><?= h($preview['page']['title']) ?></h2><p>Текущая опубликованная страница (не зафиксированная редакция) · <?= h($preview['key']) ?></p><pre class="release-text"><?= h($preview['page']['body']) ?></pre></section><?php endif ?>
<?php if($edition): $eid=(int)$edition['id']; $voted=array_map('intval',array_column($reviews,'reviewer_id')); ?>
<section class="panel"><h2>#<?= $eid ?> <?= h($edition['title']) ?></h2><p>Состояние: <?= h(['review'=>'На рецензии','changes'=>'Нужна новая редакция','approved'=>'Согласовано'][$state]) ?> · Автор #<?= (int)$edition['author_id'] ?> · Рецензенты #<?= (int)$edition['reviewer_a'] ?> и #<?= (int)$edition['reviewer_b'] ?></p><p>SHA-256 <code><?= h($edition['snapshot_hash']) ?></code></p><p>Источник: <?= h($snapshot['reader']) ?> · <?= h($snapshot['scope']) ?></p><p><a href="<?= h(url('book',['project'=>$pid,'source'=>$sid])) ?>">← Каталог / новая редакция</a> · <a href="<?= h(url('book.export',['project'=>$pid,'edition'=>$eid])) ?>">Скачать снимок JSON</a> · <a href="<?= h(url('lite',['project'=>$pid])) ?>">Публикация в Lite</a></p>
<?php foreach($snapshot['pages'] as $page): ?><article><h3><?= h($page['page']['title']) ?></h3><p><?= h($page['key']) ?> · <?= h($page['page']['locale']) ?> · <?= h($page['page']['updated']) ?> · SHA-256 <code><?= h($page['sha256']) ?></code></p><pre class="release-text"><?= h($page['page']['body']) ?></pre><?php if($page['page']['media']): ?><p>Идентификаторы медиа (файлы не архивируются): <?= h(implode(', ',$page['page']['media'])) ?></p><?php endif ?></article><?php endforeach ?></section>
<section class="panel"><h2>Рецензии</h2><?php foreach($reviews as $r): ?><p>#<?= (int)$r['reviewer_id'] ?> · <?= h($r['decision']) ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$r['created_at'])) ?> UTC · <?= h($r['note']) ?></p><?php endforeach ?>
<?php if($write&&$state==='review'&&in_array((int)$user['id'],[(int)$edition['reviewer_a'],(int)$edition['reviewer_b']],true)&&!in_array((int)$user['id'],$voted,true)): ?><form method="post"><?php formFields('book.review') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="edition_id" value="<?= $eid ?>"><input type="hidden" name="hash" value="<?= h($edition['snapshot_hash']) ?>"><label>Решение<select name="decision"><option value="approve">Согласовать снимок</option><option value="changes">Требуются исправления</option></select></label><label>Комментарий<input name="note" maxlength="1000" required></label><button class="primary">Зафиксировать решение (MFA)</button></form><?php endif ?></section>
<section class="panel"><h2>Связанные выпуски</h2><?php foreach($links as $l): ?><p><a href="<?= h(url('releases',['project'=>$pid,'id'=>$l['release_id']])) ?>"><?= h($l['tag']) ?></a> · <code><?= h($l['commit_sha']) ?></code></p><?php endforeach ?>
<?php if($manage&&$state==='approved'): ?><p><a href="<?= h(url('editorial',['project'=>$pid,'edition'=>$eid])) ?>">Создать или открыть редакторский выпуск</a></p><?php endif ?><?php if($manage&&$state==='approved'&&$releases): ?><form method="post"><?php formFields('book.release') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="edition_id" value="<?= $eid ?>"><input type="hidden" name="hash" value="<?= h($edition['snapshot_hash']) ?>"><label>Подтверждённый выпуск<select name="release_id" required><?php foreach($releases as $r): ?><option value="<?= (int)$r['id'] ?>"><?= h($r['tag'].' · '.$r['commit_sha']) ?></option><?php endforeach ?></select></label><p>Связь неизменяема: один снимок на привязку книги и выпуск.</p><button class="primary">Закрепить редакцию (MFA)</button></form><?php endif ?></section><?php endif ?><?php endif ?><?php endif ?>
